// Toggle the visual gating on .sched-smartfill-rule-advanced rows
// so an advanced sub-input only reads as enabled when its parent
// checkbox is checked.
function _refreshSfAdvancedGating() {
  document.querySelectorAll("#rr-sched-smartfill-rules-body .sched-smartfill-rule-advanced").forEach(adv => {
    const parentKey = adv.getAttribute("data-rr-sf-advanced-of");
    if (!parentKey) return;
    const cb = document.querySelector(`#rr-sched-smartfill-rules-body [data-rr-sf-rule="${parentKey}"]`);
    adv.classList.toggle("is-on", !!(cb && cb.checked));
  });
  // A boundary mode dims every rule below it — those rules have no effect
  // when the engine is stripped to a single availability boundary.
  const body = document.getElementById("rr-sched-smartfill-rules-body");
  const isChecked = (k) => {
    const cb = document.querySelector(`#rr-sched-smartfill-rules-body [data-rr-sf-rule="${k}"]`);
    return !!(cb && cb.checked);
  };
  const anyBoundary = isChecked("preferred_only") || isChecked("availability_only");
  if (body) body.classList.toggle("is-baseline", anyBoundary);
  // Preferred Availability Enhancement is a no-op when the preferred-only
  // boundary is on, so it's disabled while that mode is selected.
  const enhCb  = document.querySelector('#rr-sched-smartfill-rules-body [data-rr-sf-rule="preferred_enhancement"]');
  const enhRow = document.getElementById("rr-sf-enh-row");
  if (enhCb) {
    const disabled = isChecked("preferred_only");
    enhCb.disabled = disabled;
    if (enhRow) enhRow.classList.toggle("is-disabled", disabled);
  }
  // Enhancement sub-options are only interactive while the Enhancement
  // itself is checked; when it's off they're disabled and forced off.
  const enhOn = isChecked("preferred_enhancement") && !isChecked("preferred_only");
  document.querySelectorAll(
    '#rr-sched-smartfill-rules-body [data-rr-sf-rule="preferred_enhancement_contiguous"],' +
    '#rr-sched-smartfill-rules-body [data-rr-sf-rule="preferred_enhancement_extra"]',
  ).forEach((sub) => {
    sub.disabled = !enhOn;
    if (!enhOn) sub.checked = false;
  });
  // Standalone "Assign vans" toolbar button is redundant when CP-SAT is
  // on AND "Assign vans during Smart Fill" is on (engine handles vans
  // as a first-class decision inside the solve). Hide it in that case;
  // surface it again when the operator turns either off or works in
  // Manual mode, since then a separate vans-only pass is the only way
  // to fill van columns.
  const vansBtnGroup = document.querySelector(".sched-vans-rules-split");
  if (vansBtnGroup) {
    const cpsatOn = isChecked("use_cpsat_solver");
    const vansCb = document.querySelector('#rr-sched-smartfill-rules-body [data-rr-sf-vans="assign"]');
    const vansInSmartFill = !vansCb || vansCb.checked;
    const manualMode = !!(body && body.classList.contains("is-manual"));
    const redundant = cpsatOn && vansInSmartFill && !manualMode;
    vansBtnGroup.classList.toggle("is-hidden-by-engine", redundant);
    vansBtnGroup.style.display = redundant ? "none" : "";
  }
}
// Manual scheduling — when on, the rule box hides every auto-fill rule
